class Solution {
public:
    vector<vector<string>> findDuplicate(vector<string>& paths) {
        unordered_map<string, vector<string>> mp;
        for (const string& p : paths) {
            int n = p.size();
            int i = 0;
            while (i < n && p[i] != ' ') i++;
            string dir = p.substr(0, i);
            i++; // skip the space
            while (i < n) {
                int start = i;
                while (i < n && p[i] != ' ') i++;
                string token = p.substr(start, i - start);
                size_t lp = token.find('(');
                size_t rp = token.rfind(')');
                string filename = token.substr(0, lp);
                string content = token.substr(lp + 1, rp - lp - 1);
                mp[content].push_back(dir + "/" + filename);
                i++; // skip the space (or go past end)
            }
        }
        vector<vector<string>> res;
        for (auto& kv : mp) {
            if (kv.second.size() >= 2) {
                res.push_back(move(kv.second));
            }
        }
        return res;
    }
};
